package com.vpscontrol.widget;
import android.app.*;
import android.appwidget.*;
import android.os.*;
import android.content.*;
import android.content.res.ColorStateList;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import java.util.*;
import org.json.JSONArray;
/** One widget's draft presentation and selection, committed together only by Save. */
public final class WidgetSetupActivity extends Activity {
 private int widget;private boolean single;private Snapshot snapshot;private WidgetStyle draft;private boolean[] checked;
 private boolean registered;private final BroadcastReceiver updates=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(snapshot!=null&&Store.session(c)==null){snapshot=null;checked=new boolean[0];recreate();}}};
 private final List<Runnable> controls=new ArrayList<Runnable>();private SeekBar transparency;
 private Visuals colors;private FrameLayout preview;private TextView opacity;private final Handler handler=new Handler(Looper.getMainLooper());
 private final Runnable redraw=new Runnable(){public void run(){preview();}};
 private int dp(int n){return Visuals.dp(this,n);}private String tr(String vi,String en){return Store.tr(this,vi,en);}
 private TextView label(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(5),0,dp(5));return t;}
 private TextView heading(String value,int size){TextView t=label(value,size,colors.ink);t.setTypeface(Typeface.create("sans-serif-medium",0));return t;}
 private LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(1);return v;}
 private LinearLayout card(LinearLayout parent){LinearLayout v=column();v.setPadding(dp(16),dp(12),dp(16),dp(12));v.setBackground(Visuals.shape(colors.surface,dp(22)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(14);parent.addView(v,p);return v;}
 public void onCreate(Bundle saved){super.onCreate(saved);setResult(RESULT_CANCELED);widget=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);AppWidgetProviderInfo info=AppWidgetManager.getInstance(this).getAppWidgetInfo(widget);if(info==null||!getPackageName().equals(info.provider.getPackageName())){finish();return;}
  colors=new Visuals(this);single=info.provider.getClassName().endsWith("$Single");snapshot=Store.snapshot(this);draft=saved==null?WidgetStyle.load(this,widget):WidgetStyle.parse(saved.getString("draft",""));checked=new boolean[snapshot==null?0:snapshot.servers.size()];List<Snapshot.Server> previous=Widgets.selection(this,widget,snapshot);Set<String> selected=new HashSet<String>();if(saved!=null&&saved.containsKey("selection")){try{JSONArray a=new JSONArray(saved.getString("selection"));for(int i=0;i<a.length();i++)selected.add(a.getString(i));}catch(Exception ignored){}}else for(Snapshot.Server s:previous)selected.add(s.id);for(int i=0;i<checked.length;i++)checked[i]=selected.contains(snapshot.servers.get(i).id);if(single&&checked.length>0){int first=0;for(int i=0;i<checked.length;i++)if(checked[i]){first=i;break;}Arrays.fill(checked,false);checked[first]=true;}
  getWindow().setStatusBarColor(colors.bg);getWindow().setNavigationBarColor(colors.bg);getWindow().getDecorView().setSystemUiVisibility(Store.dark(this)?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
  final LinearLayout root=column();root.setBackgroundColor(colors.bg);root.setOnApplyWindowInsetsListener(new View.OnApplyWindowInsetsListener(){public WindowInsets onApplyWindowInsets(View v,WindowInsets i){v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;}});
  LinearLayout header=column();header.setPadding(dp(24),dp(16),dp(24),dp(10));header.addView(label("VPS CONTROL",11,colors.accent));header.addView(heading(tr("Tùy chỉnh widget","Customize widget"),27));root.addView(header);
  ScrollView scroll=new ScrollView(this);final LinearLayout list=column();list.setPadding(dp(20),dp(4),dp(20),dp(10));scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  LinearLayout p=card(list);p.addView(heading(tr("Xem trước","Preview"),14));preview=new FrameLayout(this);preview.setTag("widget-preview");preview.setPadding(dp(8),dp(8),dp(8),dp(8));preview.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xFF92B8C4,0xFF526E93,0xFF262D4C}));p.addView(preview,new LinearLayout.LayoutParams(-1,dp(206)));p.addView(label(tr("Màu phía sau dùng để xem độ trong suốt. Hình nền thật là hình nền màn hình chính của anh.","The backdrop illustrates transparency. Your home screen uses its own wallpaper."),11,colors.muted));
  LinearLayout appearance=card(list);appearance.addView(heading(tr("Giao diện riêng","Appearance"),19));
  choice(appearance,tr("Nền và màu chữ","Theme"),"theme",new String[]{"app","light","dark"},new String[]{tr("Theo ứng dụng","Follow app"),tr("Sáng dịu","Soft light"),tr("Tối","Dark")});
  opacity=label("",13,colors.ink);appearance.addView(opacity);SeekBar alpha=new SeekBar(this);transparency=alpha;alpha.setTag("style:transparency");alpha.setMax(100);alpha.setProgress(draft.transparency);alpha.setProgressTintList(ColorStateList.valueOf(colors.accent));alpha.setThumbTintList(ColorStateList.valueOf(colors.accent));appearance.addView(alpha,new LinearLayout.LayoutParams(-1,dp(42)));alpha.setContentDescription(tr("Độ trong suốt nền, từ 0 đến 100 phần trăm","Background transparency, zero to one hundred percent"));alpha.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int value,boolean user){draft.transparency=value;opacityText();changed();}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){handler.removeCallbacks(redraw);preview();}});opacityText();
  choice(appearance,tr("Màu nhấn","Accent"),"accent",new String[]{"violet","blue","teal","amber"},new String[]{tr("Tím","Violet"),tr("Xanh dương","Blue"),tr("Xanh ngọc","Teal"),tr("Hổ phách","Amber")});
  LinearLayout layout=card(list);layout.addView(heading(tr("Cách hiển thị","Display"),19));choice(layout,tr("Kiểu tài nguyên","Resource style"),"layout",new String[]{"auto","rings","bars","numbers"},new String[]{tr("Tự động","Automatic"),tr("Đồng hồ","Gauges"),tr("Bar ngang","Horizontal bars"),tr("Chữ và số","Numbers")});choice(layout,tr("Mật độ danh sách","List density"),"density",new String[]{"comfortable","compact"},new String[]{tr("Thoáng","Comfortable"),tr("Gọn","Compact")});layout.addView(label(tr("Mật độ áp dụng cho nhiều VPS. Kéo đổi kích thước trên màn hình chính để có thanh ngang. Widget nhỏ sẽ tự rút gọn.","Density applies to multiple servers. Resize the widget on your home screen for a wide bar. Small sizes simplify the layout."),11,colors.muted));
  LinearLayout servers=card(list);servers.addView(heading(tr("Máy chủ hiển thị","Servers"),19));if(checked.length==0){servers.addView(label(tr("Ghép nối và cập nhật trong ứng dụng để chọn VPS. Anh vẫn có thể lưu giao diện trước.","Pair and refresh in the app to select servers. You can save the appearance first."),14,colors.muted));}else{
   final CompoundButton[] options=new CompoundButton[checked.length];for(int i=0;i<checked.length;i++){final int index=i;CompoundButton item=single?new RadioButton(this):new CheckBox(this);options[i]=item;item.setText(snapshot.servers.get(i).name);item.setTag("server:"+i);item.setTextSize(15);item.setTextColor(colors.ink);item.setButtonTintList(ColorStateList.valueOf(colors.accent));item.setChecked(checked[i]);item.setPadding(dp(4),dp(7),dp(4),dp(7));servers.addView(item,new LinearLayout.LayoutParams(-1,-2));item.setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(single){Arrays.fill(checked,false);checked[index]=true;for(int n=0;n<options.length;n++)options[n].setChecked(n==index);}else checked[index]=((CompoundButton)v).isChecked();changed();}});}}
  action(list,tr("Khôi phục giao diện mặc định","Reset appearance"),"style:reset",new View.OnClickListener(){public void onClick(View v){draft=new WidgetStyle();for(Runnable r:controls)r.run();transparency.setProgress(draft.transparency);opacityText();preview();}});
  LinearLayout buttons=new LinearLayout(this);buttons.setPadding(dp(20),dp(8),dp(20),dp(14));TextView cancel=action(buttons,tr("Hủy","Cancel"),"style:cancel",new View.OnClickListener(){public void onClick(View v){finish();}});TextView save=action(buttons,tr("Lưu widget","Save widget"),"style:save",new View.OnClickListener(){public void onClick(View v){save();}});save.setTextColor(Store.dark(this)?0xFF201638:0xFFFFFFFF);save.setBackground(Visuals.shape(colors.accent,dp(16)));root.addView(buttons);setContentView(root);root.requestApplyInsets();preview.post(redraw);
 }
 public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);if(draft!=null){out.putString("draft",draft.json());out.putString("selection",selection().toString());}}
 private JSONArray selection(){JSONArray a=new JSONArray();if(snapshot!=null)for(int i=0;i<checked.length;i++)if(checked[i])a.put(snapshot.servers.get(i).id);return a;}
 private void opacityText(){opacity.setText(tr("Độ trong suốt nền: ","Background transparency: ")+draft.transparency+"%  ·  "+tr("chữ luôn rõ","text stays opaque"));}
 private void changed(){handler.removeCallbacks(redraw);handler.postDelayed(redraw,90);}
 private String value(String name){return name.equals("theme")?draft.theme:name.equals("accent")?draft.accent:name.equals("density")?draft.density:draft.layout;}
 private void choice(LinearLayout parent,final String title,final String name,final String[] values,final String[] labels){final LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(8),0,dp(8));row.setTag("style:"+name);LinearLayout copy=column();copy.addView(heading(title,14));final TextView current=label("",13,colors.muted);current.setTag("value:"+name);copy.addView(current);row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));row.addView(label("›",26,colors.accent));parent.addView(row);final Runnable refresh=new Runnable(){public void run(){int index=0;for(int i=0;i<values.length;i++)if(values[i].equals(value(name)))index=i;current.setText(labels[index]);row.setContentDescription(title+": "+labels[index]);}};controls.add(refresh);refresh.run();row.setOnClickListener(new View.OnClickListener(){public void onClick(View view){int selected=0;for(int i=0;i<values.length;i++)if(values[i].equals(value(name)))selected=i;new AlertDialog.Builder(WidgetSetupActivity.this,Store.dark(WidgetSetupActivity.this)?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert).setTitle(title).setSingleChoiceItems(labels,selected,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int index){if(name.equals("theme"))draft.theme=values[index];else if(name.equals("accent"))draft.accent=values[index];else if(name.equals("density"))draft.density=values[index];else draft.layout=values[index];d.dismiss();refresh.run();preview();}}).setNegativeButton(tr("Hủy","Cancel"),null).show();}});}
 private TextView action(LinearLayout parent,String title,String tag,View.OnClickListener click){TextView t=label(title,15,colors.accent);t.setGravity(Gravity.CENTER);t.setMinHeight(dp(48));t.setTag(tag);t.setBackground(Visuals.shape(colors.inset,dp(16)));t.setOnClickListener(click);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(parent.getOrientation()==LinearLayout.HORIZONTAL?0:-1,-2,parent.getOrientation()==LinearLayout.HORIZONTAL?1:0);p.setMargins(dp(3),dp(6),dp(3),0);parent.addView(t,p);return t;}
 private void preview(){if(preview==null||isFinishing())return;int available=Math.max(110,Math.round(preview.getWidth()/getResources().getDisplayMetrics().density)-16);AppWidgetManager manager=AppWidgetManager.getInstance(this);Bundle options=manager.getAppWidgetOptions(widget);int w=Math.max(110,options.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,single?160:280)),h=Math.max(110,options.getInt(AppWidgetManager.OPTION_APPWIDGET_MAX_HEIGHT,single?160:180));float scale=Math.min(1f,Math.min(available/(float)w,190f/h));List<Snapshot.Server> selected=new ArrayList<Snapshot.Server>();if(snapshot!=null)for(int i=0;i<checked.length;i++)if(checked[i])selected.add(snapshot.servers.get(i));View view=Widgets.render(this,widget,single,w,h,snapshot,draft,selected).apply(this,preview);disable(view);view.setPivotX(0);view.setPivotY(0);view.setScaleX(scale);view.setScaleY(scale);FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(dp(w),dp(h));p.leftMargin=dp(8)+Math.round((dp(available)-dp(w)*scale)/2);p.topMargin=dp(8);preview.removeAllViews();preview.addView(view,p);}
 private void disable(View v){v.setClickable(false);v.setFocusable(false);v.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);if(v instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)v).getChildCount();i++)disable(((android.view.ViewGroup)v).getChildAt(i));}
 private void save(){if(checked.length>0&&selection().length()==0){Toast.makeText(this,tr("Chọn ít nhất một VPS.","Select at least one server."),Toast.LENGTH_SHORT).show();return;}AppWidgetProviderInfo info=AppWidgetManager.getInstance(this).getAppWidgetInfo(widget);if(info==null||!getPackageName().equals(info.provider.getPackageName())){finish();return;}if(!Store.saveWidget(this,widget,checked.length==0?"":selection().toString(),WidgetStyle.parse(draft.json()).json())){Toast.makeText(this,tr("Chưa lưu được. Anh thử lại nhé.","Could not save. Please retry."),Toast.LENGTH_SHORT).show();return;}Widgets.update(this,AppWidgetManager.getInstance(this),widget);Sync.schedule(this);setResult(RESULT_OK,new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widget));finish();}
 public void onResume(){super.onResume();IntentFilter filter=new IntentFilter(Sync.CHANGED);if(android.os.Build.VERSION.SDK_INT>=33)registerReceiver(updates,filter,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(updates,filter);registered=true;if(snapshot!=null&&Store.session(this)==null){snapshot=null;checked=new boolean[0];recreate();}}
 public void onPause(){if(registered){unregisterReceiver(updates);registered=false;}super.onPause();}
 public void onDestroy(){handler.removeCallbacks(redraw);super.onDestroy();}
}
